&lt;div class="crayons-story__indention"&gt;
&lt;h2 class="crayons-story__title crayons-story__title-full_post"&gt;
&lt;a href="https://dev.to/smoren/building-explicit-data-flow-graphs-in-typescript-introducing-transferum-3f23" id="article-link-4194118"&gt;
Building explicit data-flow graphs in TypeScript: Introducing Transferum
&lt;/a&gt;
&lt;/h2&gt;
&lt;div class="crayons-story__tags"&gt;
&lt;a class="crayons-tag  crayons-tag--monochrome " href="/t/typescript"&gt;&lt;span class="crayons-tag__prefix"&gt;#&lt;/span&gt;typescript&lt;/a&gt;
&lt;a class="crayons-tag  crayons-tag--monochrome " href="/t/opensource"&gt;&lt;span class="crayons-tag__prefix"&gt;#&lt;/span&gt;opensource&lt;/a&gt;
&lt;a class="crayons-tag  crayons-tag--monochrome " href="/t/frp"&gt;&lt;span class="crayons-tag__prefix"&gt;#&lt;/span&gt;frp&lt;/a&gt;
&lt;a class="crayons-tag  crayons-tag--monochrome " href="/t/rxjs"&gt;&lt;span class="crayons-tag__prefix"&gt;#&lt;/span&gt;rxjs&lt;/a&gt;
&lt;/div&gt;
&lt;div class="crayons-story__bottom"&gt;
&lt;div class="crayons-story__details"&gt;
&lt;a href="https://dev.to/smoren/building-explicit-data-flow-graphs-in-typescript-introducing-transferum-3f23" class="crayons-btn crayons-btn--s crayons-btn--ghost crayons-btn--icon-left"&gt;
&lt;div class="multiple_reactions_aggregate"&gt;
&lt;span class="multiple_reactions_icons_container"&gt;
&lt;span class="crayons_icon_container"&gt;
&lt;img src="https://assets.dev.to/assets/multi-unicorn-b44d6f8c23cdd00964192bedc38af3e82463978aa611b4365bd33a0f1f4f3e97.svg" width="24" height="24"&gt;
&lt;/span&gt;
&lt;span class="crayons_icon_container"&gt;
&lt;img src="https://assets.dev.to/assets/fire-f60e7a582391810302117f987b22a8ef04a2fe0df7e3258a5f49332df1cec71e.svg" width="24" height="24"&gt;
&lt;/span&gt;
&lt;span class="crayons_icon_container"&gt;
&lt;img src="https://assets.dev.to/assets/sparkle-heart-5f9bee3767e18deb1bb725290cb151c25234768a0e9a2bd39370c382d02920cf.svg" width="24" height="24"&gt;
&lt;/span&gt;
&lt;/span&gt;
&lt;span class="aggregate_reactions_counter"&gt;8&lt;span class="hidden s:inline"&gt;&amp;nbsp;reactions&lt;/span&gt;&lt;/span&gt;
